// src/facets/menus.rs — the facet's own module; src/main.rs adds its two FACET WIRING lines.
// World (src/main.rs) derives Default, Serialize and Deserialize (with
// #[serde(crate = "genex::serde")]) and holds coins: u32, paused: bool and opened: u64 (the tick the pause menu opened). Every word is a key in
// assets/lang/en.ftl.
use super::World;
use genex::prelude::*;
use genex::saves::{SaveConfig, SlotOp};
use genex::ui::{tr, Menu, ToastKind, Toasts};

pub fn wire(game: &mut Game<World>) {
    game.ui(UiConfig::new().locales(&["en"]));
    // Slots hold the whole world; the ring autosaves every minute of play into two slots
    // (and on a phone's suspend); a player keeps at most three named slots.
    game.saves(SaveConfig::schema(1).autosave(3600, 2).slots_max(3));
    game.save_world();
    game.on_update(|sim, ctx| {
        if !sim.world.paused && ctx.keys.pressed(Key::Escape) {
            sim.world.paused = true;
            sim.world.opened = ctx.tick;
        }
    });
    game.on_ui(|sim, ui, ctx| {
        let slots = ctx.slots();
        // A queued save or load finishes as an event on a later tick: say so with a toast.
        for event in slots.events() {
            let (kind, key) = match (&event.result, event.op) {
                (Err(_), _) => (ToastKind::Error, "toast-refused"),
                (Ok(_), SlotOp::Load) => (ToastKind::Success, "toast-loaded"),
                _ => (ToastKind::Success, "toast-saved"),
            };
            Toasts::push(ui.ctx(), kind, &tr(key));
        }
        Toasts::show(ui);
        if !sim.world.paused {
            return;
        }
        // Keys pause.resume, pause.save and pause.load: a check finds each in state().hud.widgets.
        let (resume, save, load) = (tr("pause-resume"), tr("pause-save"), tr("pause-load"));
        let picked = Menu::new("pause").item("resume", &resume).item("save", &save).item("load", &load).back("resume").show(ui);
        // The press that opened the menu (Escape, also its back key) never picks in it.
        if sim.world.opened == ctx.tick {
            return;
        }
        match picked {
            // While a load is queued a save refuses save-busy: wait for its event instead.
            Some("save") if !slots.busy() => {
                slots.save("slot-1", &tr("slot-label")).ok();
            }
            Some("load") => {
                slots.load("slot-1").ok();
            }
            Some("resume") => sim.world.paused = false,
            _ => {}
        }
    });
    game.probe("coins", |sim| json!(sim.world.coins));
}
